dashboard.definition:
{
  "title": "Data Topology",
  "description": "Click a data source for latest event, volume, trend, and drop/burst outliers.",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-4h@h,now"
      }
    },
    "input_source": {
      "type": "input.text",
      "title": "Selected data source (set by clicking data_source)",
      "options": {
        "token": "tok_data_source",
        "defaultValue": "none"
      }
    }
  },
  "dataSources": {
    "ds_topo_paths": {
      "type": "ds.search",
      "name": "Indexed source \u2192 ingest \u2192 index",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` by host sourcetype source index\n| rex field=source \"(?i)(?:^|[^A-Za-z])(?<net_proto>tcp|udp)[:/](?<net_port>\\d+)\"\n| eval net_label=case(\n    lower(net_proto)=\"udp\" AND isnotnull(net_port), \"UDP:\".net_port,\n    lower(net_proto)=\"tcp\" AND isnotnull(net_port), \"TCP:\".net_port,\n    1=1, null())\n| eval os_class=case(\n    match(sourcetype, \"(?i)wineventlog|WinHostMon|XmlWinEventLog|^Perfmon|WinRegistry|powershell|^windows:|MSAD:|DhcpSrvLog|^IIS\"), \"Windows\",\n    match(source, \"(?i)WinEventLog|Perfmon:|\\\\\\\\Windows\\\\\\\\\"), \"Windows\",\n    match(sourcetype, \"(?i)^linux_|^osnix|^unix:|^auditd|^journald|^selinux|^secure$|^messages$|^df$|^cpu$|^iostat|^vmstat|^interfaces|^lastlog|^openPorts|^hardware|^netstat|^yum\"), \"Linux\",\n    match(source, \"(?i)^/var/|^/opt/|^/etc/|^/usr/|^/home/\"), \"Linux\",\n    1=1, null())\n| append [\n    search index=_internal source=*metrics.log group=tcpin_connections\n    | eval host=coalesce(sourceHost, hostname)\n    | eval fwd=lower(trim(coalesce(fwdType, \"\")))\n    | eval conn=lower(trim(coalesce(connectionType, \"\")))\n    | eval forwarder_class=case(\n        match(fwd, \"^(uf|lwf)$\"), \"UF\",\n        match(fwd, \"^(full|hf|hwf)$\"), \"HF\",\n        1=1, null())\n    | eval metrics_net=if(isnull(forwarder_class) AND match(conn, \"raw\") AND isnum(coalesce(destPort, dest_port)), \"TCP:\".coalesce(destPort, dest_port), null())\n    | where isnotnull(host) AND (isnotnull(forwarder_class) OR isnotnull(metrics_net))\n    | stats latest(forwarder_class) as forwarder_class, latest(metrics_net) as metrics_net by host\n]\n| append [\n    search index=_internal source=*metrics.log group=udpin_connections\n    | eval host=coalesce(sourceHost, hostname)\n    | eval metrics_net=\"UDP:\".coalesce(destPort, dest_port, port)\n    | where isnotnull(host) AND match(metrics_net, \"^UDP:[0-9]+$\")\n    | stats latest(metrics_net) as metrics_net by host\n]\n| eventstats latest(forwarder_class) as forwarder_class, latest(metrics_net) as metrics_net by host\n| eventstats values(os_class) as os_classes by host\n| where isnotnull(events)\n| eval host_os=case(\n    isnotnull(mvfind(os_classes, \"Windows\")), \"Windows\",\n    isnotnull(mvfind(os_classes, \"Linux\")), \"Linux\",\n    1=1, os_class)\n| eval net_label=coalesce(net_label, metrics_net)\n| eval ingest_path=case(\n    match(sourcetype, \"(?i)httpevent|^aws:|^azure:|^gcp:|^google:|kube:container\"), \"HEC / API / cloud\",\n    match(sourcetype, \"(?i)edge.?processor|ingest.?processor\"), \"Edge / Ingest Processor\",\n    match(sourcetype, \"(?i)sc4s\"), \"SC4S\",\n    forwarder_class=\"HF\", \"HF\",\n    forwarder_class=\"UF\" AND host_os=\"Windows\", \"Windows UF\",\n    forwarder_class=\"UF\", \"Linux UF\",\n    host_os=\"Windows\", \"Windows UF\",\n    isnotnull(net_label), \"Other \".net_label,\n    1=1, \"Other\")\n| stats sum(events) as events by host, ingest_path, index\n| sort 0 -events\n| head 100\n| rename host as data_source, index as splunk_index\n| eval _color_rank=3\n| table data_source, ingest_path, splunk_index, events, _color_rank",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_topo_sankey": {
      "type": "ds.chain",
      "name": "Indexed flow sankey",
      "options": {
        "extend": "ds_topo_paths",
        "query": "| eval source=data_source, target=ingest_path, value=events\n| appendpipe [\n    eval source=ingest_path, target=splunk_index, value=events\n    | fields source, target, value\n]\n| stats sum(value) as value by source, target\n| eval value=tonumber(value)\n| where value>0 AND isnotnull(source) AND isnotnull(target)\n| table source, target, value"
      }
    },
    "ds_topo_counts": {
      "type": "ds.chain",
      "name": "Topology counts",
      "options": {
        "extend": "ds_topo_paths",
        "query": "| stats dc(data_source) as sources, dc(ingest_path) as ingest_paths, dc(splunk_index) as indexes, sum(events) as events"
      }
    },
    "ds_topo_src_stats": {
      "type": "ds.search",
      "name": "Selected source latest and totals",
      "options": {
        "query": "| tstats count as events, latest(_time) as last_event, earliest(_time) as first_event, dc(sourcetype) as sourcetypes where index=`exec_health_idx` host=\"$tok_data_source$\"\n| eval data_source=replace(\"$tok_data_source$\", \"[^A-Za-z0-9._:-]\", \"\")\n| where data_source!=\"none\" AND data_source!=\"\" AND data_source!=\"*\"\n| eval age_min=round((now()-last_event)/60, 0)\n| eval last_event=strftime(last_event, \"%Y-%m-%d %H:%M:%S\")\n| eval first_event=strftime(first_event, \"%Y-%m-%d %H:%M:%S\")\n| eval _color_rank=if(age_min>(`exec_health_silence_sec`/60), 1, 3)\n| table data_source, first_event, last_event, events, sourcetypes, _color_rank",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_topo_src_trend": {
      "type": "ds.search",
      "name": "Selected source 24h trend",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` host=\"$tok_data_source$\" earliest=-25h@m latest=@m by _time span=15m\n| eval data_source=replace(\"$tok_data_source$\", \"[^A-Za-z0-9._:-]\", \"\")\n| where data_source!=\"none\" AND data_source!=\"\" AND data_source!=\"*\"\n| timechart span=15m sum(events) as events\n| fillnull value=0 events\n| streamstats window=96 current=f avg(events) as mean_vol stdev(events) as stdev_vol count as samples\n| eval sigma=`exec_health_sigma`\n| eval mean=if(samples>=8, round(mean_vol, 1), null())\n| eval drop_bound=if(samples>=8 AND stdev_vol>0, round(mean_vol-(sigma*stdev_vol), 1), null())\n| eval burst_bound=if(samples>=8 AND stdev_vol>0, round(mean_vol+(sigma*stdev_vol), 1), null())\n| eval drop_bound=if(drop_bound<0, 0, drop_bound)\n| table _time, events, mean, drop_bound, burst_bound",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-25h@m",
          "latest": "@m"
        }
      }
    },
    "ds_topo_src_outliers": {
      "type": "ds.search",
      "name": "Selected source drop/burst outliers",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` host=\"$tok_data_source$\" earliest=-25h@m latest=@m by _time span=15m\n| eval data_source=replace(\"$tok_data_source$\", \"[^A-Za-z0-9._:-]\", \"\")\n| where data_source!=\"none\" AND data_source!=\"\" AND data_source!=\"*\"\n| timechart span=15m sum(events) as events\n| fillnull value=0 events\n| streamstats window=96 current=f avg(events) as mean_vol stdev(events) as stdev_vol count as samples\n| where _time+900+300 <= now()\n| eval sigma=`exec_health_sigma`\n| eval mean_vol=round(mean_vol, 1), stdev_vol=round(stdev_vol, 1)\n| eval drop_bound=round(mean_vol-(sigma*stdev_vol), 1), burst_bound=round(mean_vol+(sigma*stdev_vol), 1)\n| eval z_score=if(stdev_vol>0, round((events-mean_vol)/stdev_vol, 2), 0)\n| eval outlier=case(\n    samples<8, \"WARMUP\",\n    stdev_vol>0 AND events < drop_bound AND mean_vol>10, \"DROP\",\n    stdev_vol>0 AND events > burst_bound AND events>10, \"BURST\",\n    1=1, \"OK\")\n| where outlier=\"DROP\" OR outlier=\"BURST\"\n| eval _color_rank=if(outlier=\"DROP\", 1, 2)\n| eval bucket=strftime(_time, \"%Y-%m-%d %H:%M\")\n| eval data_source=replace(\"$tok_data_source$\", \"[^A-Za-z0-9._:-]\", \"\")\n| sort -_time\n| table bucket, data_source, events, mean_vol, stdev_vol, z_score, outlier, _color_rank",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-25h@m",
          "latest": "@m"
        }
      }
    },
    "ds_tcpin": {
      "type": "ds.search",
      "name": "Forwarder \u2192 indexer connections",
      "options": {
        "query": "search index=_internal source=*metrics.log group=tcpin_connections\n| eval data_source=coalesce(sourceHost, hostname)\n| eval receiver=host\n| eval fwd=lower(trim(coalesce(fwdType, \"\")))\n| eval connection=case(\n    match(fwd, \"^(uf|lwf)$\"), \"UF\",\n    match(fwd, \"^(full|hf|hwf)$\"), \"HF\",\n    match(lower(coalesce(connectionType, \"\")), \"raw\"), \"TCP raw\",\n    1=1, coalesce(fwdType, connectionType, \"s2s\"))\n| where isnotnull(data_source) AND isnotnull(receiver)\n| stats sum(kb) as kb, sum(tcp_eps) as eps by data_source, connection, receiver\n| eval kb=round(kb, 1), eps=round(eps, 2)\n| sort 0 -kb\n| head 80\n| eval _color_rank=3\n| table data_source, connection, receiver, kb, eps, _color_rank",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_tcpin_sankey": {
      "type": "ds.chain",
      "name": "Forwarder flow sankey",
      "options": {
        "extend": "ds_tcpin",
        "query": "| eval source=data_source, target=receiver, value=kb\n| where isnotnull(source) AND isnotnull(target) AND value>0\n| stats sum(value) as value by source, target\n| fields source, target, value"
      }
    },
    "ds_tcpin_counts": {
      "type": "ds.chain",
      "name": "Forwarder connection counts",
      "options": {
        "extend": "ds_tcpin",
        "query": "| stats dc(data_source) as forwarders, dc(receiver) as receivers, sum(kb) as kb"
      }
    },
    "ds_top_indexes": {
      "type": "ds.search",
      "name": "Top indexes by GB",
      "options": {
        "query": "search `exec_health_license_usage`\n| eval GB=round(b/1024/1024/1024, 3)\n| stats sum(GB) as GB by idx\n| rename idx as index\n| sort 0 -GB\n| head 20\n| eval _color_rank=3",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_topo_link": {
      "type": "ds.chain",
      "name": "Indexed topology nodes only",
      "options": {
        "extend": "ds_topo_paths",
        "query": "| table data_source, ingest_path, splunk_index"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Data topology\nHow servers and data sources reach Splunk: **data source \u2192 ingest path \u2192 index**, plus **forwarder \u2192 indexer** from `_internal` `tcpin_connections`. **Click a data_source** in the graph or table for latest event, totals, 24-hour trend, and sudden drops or bursts. Search does not open.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_sources": {
      "type": "splunk.singlevalue",
      "title": "Data sources",
      "dataSources": {
        "primary": "ds_topo_counts"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"sources\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_paths": {
      "type": "splunk.singlevalue",
      "title": "Ingest paths",
      "dataSources": {
        "primary": "ds_topo_counts"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"ingest_paths\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_indexes": {
      "type": "splunk.singlevalue",
      "title": "Destination indexes",
      "dataSources": {
        "primary": "ds_topo_counts"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"indexes\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_fwds": {
      "type": "splunk.singlevalue",
      "title": "Forwarders (tcpin)",
      "dataSources": {
        "primary": "ds_tcpin_counts"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"forwarders\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_link": {
      "type": "splunk.linkgraph",
      "title": "Sources \u2192 ingest path \u2192 Splunk index",
      "dataSources": {
        "primary": "ds_topo_link"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "fieldOrder": [
          "data_source",
          "ingest_path",
          "splunk_index"
        ],
        "linkColor": "#58A6FF",
        "nodeHighlightColor": "#A371F7",
        "nodeWidth": 170,
        "nodeHeight": 22,
        "nodeSpacingX": 40,
        "nodeSpacingY": 12,
        "resultLimit": 40,
        "showNodeCounts": true,
        "showValueCounts": true,
        "backgroundColor": "transparent"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "tok_data_source",
                "key": "row.data_source.value"
              }
            ]
          }
        }
      ]
    },
    "viz_sankey": {
      "type": "splunk.sankey",
      "title": "Volume flow (events) through ingest paths",
      "dataSources": {
        "primary": "ds_topo_sankey"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "colorMode": "categorical",
        "linkOpacity": 0.6,
        "seriesColors": [
          "#58A6FF",
          "#3FB950",
          "#E3B341",
          "#F85149",
          "#A371F7"
        ],
        "backgroundColor": "transparent"
      }
    },
    "viz_top_indexes": {
      "type": "splunk.table",
      "title": "Top indexes by license usage (GB)",
      "dataSources": {
        "primary": "ds_top_indexes"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "count": 15,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)",
          "headerBackgroundColor": "transparent",
          "headerColor": "#8B949E"
        },
        "columnFormat": {
          "severity": {
            "rowColors": "> table | seriesByName(\"severity\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(pillBg)"
          },
          "status": {
            "rowColors": "> table | seriesByName(\"status\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(pillBg)"
          },
          "state": {
            "rowColors": "> table | seriesByName(\"state\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"state\") | matchValue(pillBg)"
          },
          "baseline_state": {
            "rowColors": "> table | seriesByName(\"baseline_state\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"baseline_state\") | matchValue(pillBg)"
          },
          "latency_state": {
            "rowColors": "> table | seriesByName(\"latency_state\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"latency_state\") | matchValue(pillBg)"
          },
          "hec_state": {
            "rowColors": "> table | seriesByName(\"hec_state\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"hec_state\") | matchValue(pillBg)"
          },
          "tile_status": {
            "rowColors": "> table | seriesByName(\"tile_status\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"tile_status\") | matchValue(pillBg)"
          },
          "decision": {
            "rowColors": "> table | seriesByName(\"decision\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"decision\") | matchValue(pillBg)"
          },
          "recurring": {
            "rowColors": "> table | seriesByName(\"recurring\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"recurring\") | matchValue(pillBg)"
          }
        },
        "backgroundColor": "transparent"
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#2A1519"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#262011"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#151D2F"
          }
        ],
        "pillText": [
          {
            "match": "RED",
            "value": "#F85149"
          },
          {
            "match": "ALERT",
            "value": "#F85149"
          },
          {
            "match": "HOST DOWN",
            "value": "#F85149"
          },
          {
            "match": "DATA SILENT",
            "value": "#F85149"
          },
          {
            "match": "HEARTBEAT ONLY",
            "value": "#F85149"
          },
          {
            "match": "HIGH",
            "value": "#F85149"
          },
          {
            "match": "CLOCK AHEAD",
            "value": "#F85149"
          },
          {
            "match": "FAILED",
            "value": "#F85149"
          },
          {
            "match": "failed",
            "value": "#F85149"
          },
          {
            "match": "FAIL",
            "value": "#F85149"
          },
          {
            "match": "MISCONFIG",
            "value": "#F85149"
          },
          {
            "match": "STALLED",
            "value": "#F85149"
          },
          {
            "match": "YELLOW",
            "value": "#E3B341"
          },
          {
            "match": "DELAYED",
            "value": "#E3B341"
          },
          {
