          {
            "match": "WAIT",
            "value": "#8B949E"
          }
        ],
        "pillBg": [
          {
            "match": "RED",
            "value": "#3D1418"
          },
          {
            "match": "ALERT",
            "value": "#3D1418"
          },
          {
            "match": "HOST DOWN",
            "value": "#3D1418"
          },
          {
            "match": "DATA SILENT",
            "value": "#3D1418"
          },
          {
            "match": "HEARTBEAT ONLY",
            "value": "#3D1418"
          },
          {
            "match": "HIGH",
            "value": "#3D1418"
          },
          {
