            "value": "#3D1418"
          },
          {
            "match": "FAILED",
            "value": "#3D1418"
          },
          {
            "match": "failed",
            "value": "#3D1418"
          },
          {
            "match": "FAIL",
            "value": "#3D1418"
          },
          {
            "match": "MISCONFIG",
            "value": "#3D1418"
          },
          {
            "match": "STALLED",
            "value": "#3D1418"
          },
          {
            "match": "YELLOW",
            "value": "#3A2E0C"
          },
          {
            "match": "DELAYED",
            "value": "#3A2E0C"
          },
          {
            "match": "WARMUP",
            "value": "#3A2E0C"
          },
          {
            "match": "WATCH",
            "value": "#3A2E0C"
          },
          {
            "match": "N/A",
            "value": "#3A2E0C"
          },
          {
            "match": "open",
            "value": "#3A2E0C"
          },
          {
            "match": "TESTING",
            "value": "#3A2E0C"
          },
          {
            "match": "WAITING",
            "value": "#3A2E0C"
          },
